107	/**
108	 * Product + offers for a non-VPS product line (shared hosting, game servers).
109	 * Kept alongside the VPS-specific ProductJsonLd so each product line can emit a
110	 * distinct Product entity with its own name/description/url. Prices are in USD
111	 * dollars (e.g. 3.99); NaN/zero offers are dropped so we never advertise a price
112	 * we don't charge.
113	 */
114	export function ProductOffersJsonLd({
115	  name,
116	  description,
117	  url,
118	  offers,
119	}: {
120	  name: string;
121	  description: string;
122	  url: string;
123	  offers: Array<{ name: string; price: number }>;
124	}) {
125	  const priced = offers.filter((o) => Number.isFinite(o.price) && o.price > 0);
126	  return (
127	    <JsonLd
128	      data={{
129	        "@context": "https://schema.org",
130	        "@type": "Product",
131	        name,
132	        description,
133	        brand: { "@type": "Brand", name: "Nxeon" },
134	        offers: {
135	          "@type": "AggregateOffer",
136	          priceCurrency: "USD",
137	          lowPrice: priced.length ? Math.min(...priced.map((o) => o.price)).toFixed(2) : undefined,
138	          offerCount: priced.length,
139	          offers: priced.map((o) => ({
140	            "@type": "Offer",
141	            name: o.name,
142	            price: o.price.toFixed(2),
143	            priceCurrency: "USD",
144	            availability: "https://schema.org/InStock",
145	            url,
146	          })),
147	        },
148	      }}
