3	import { revalidatePath } from "next/cache";
4	import { z } from "zod";
5	import { db } from "@/lib/db";
6	import { requireArea } from "@/lib/rbac";
7	import { setSetting } from "@/lib/settings";
8	import { logEvent } from "@/lib/log";
9	
10	type ActionState = { error?: string; ok?: boolean };
11	
12	const SOURCES = ["INTERNAL", "GOOGLE", "TRUSTPILOT", "HOSTADVICE"] as const;
13	
14	const schema = z.object({
15	  id: z.string().optional(),
16	  author: z.string().min(1, "Author name is required.").max(80),
17	  role: z.string().max(120).optional(),
18	  body: z.string().min(1, "Review text is required.").max(2000),
19	  rating: z.coerce.number().int().min(1).max(5).default(5),
20	  source: z.enum(SOURCES).default("INTERNAL"),
21	  approved: z.boolean(),
22	  featured: z.boolean(),
23	});
24	
25	function revalidate() {
26	  revalidatePath("/admin/reviews");
27	  revalidatePath("/"); // homepage badges + "what our customers say" section
28	}
29	
30	/** Create or update a review. Wired to a <form> via useActionState. */
31	export async function saveReview(_prev: ActionState, formData: FormData): Promise<ActionState> {
32	  await requireArea("platform");
33	
34	  const parsed = schema.safeParse({
35	    id: (formData.get("id") as string) || undefined,
36	    author: formData.get("author"),
37	    role: (formData.get("role") as string) || undefined,
38	    body: formData.get("body"),
39	    rating: formData.get("rating") ?? 5,
40	    source: (formData.get("source") as string) || "INTERNAL",
41	    approved: formData.get("approved") === "on" || formData.get("approved") === "true",
42	    featured: formData.get("featured") === "on" || formData.get("featured") === "true",
43	  });
44	
45	  if (!parsed.success) {
46	    return { error: parsed.error.issues[0]?.message ?? "Invalid review." };
47	  }
48	
49	  const { id, role, ...rest } = parsed.data;
50	  const data = { ...rest, role: role || null };
51	
52	  try {
53	    if (id) {
54	      const existing = await db.review.findUnique({ where: { id } });
55	      if (!existing) return { error: "Review not found." };
56	      await db.review.update({ where: { id }, data });
57	    } else {
58	      await db.review.create({ data });
59	    }
60	  } catch (err) {
61	    await logEvent("error", "review.save", { message: String(err), author: data.author });
62	    return { error: "Could not save the review. Please try again." };
63	  }
64	
65	  revalidate();
66	  return { ok: true };
67	}
68	
69	/** Toggle whether a review is publicly shown. */
70	export async function toggleReviewApproved(id: string): Promise<ActionState> {
71	  await requireArea("platform");
72	  const r = await db.review.findUnique({ where: { id } });
73	  if (!r) return { error: "Review not found." };
74	  await db.review.update({ where: { id }, data: { approved: !r.approved } });
75	  revalidate();
76	  return { ok: true };
77	}
78	
79	/** Toggle whether a review floats to the top of the display section. */
80	export async function toggleReviewFeatured(id: string): Promise<ActionState> {
81	  await requireArea("platform");
82	  const r = await db.review.findUnique({ where: { id } });
83	  if (!r) return { error: "Review not found." };
84	  await db.review.update({ where: { id }, data: { featured: !r.featured } });
85	  revalidate();
86	  return { ok: true };
87	}
88	
89	/** Permanently delete a review. */
90	export async function deleteReview(id: string): Promise<ActionState> {
91	  await requireArea("platform");
92	  const r = await db.review.findUnique({ where: { id } });
93	  if (!r) return { error: "Review not found." };
94	  await db.review.delete({ where: { id } });
95	  revalidate();
96	  return { ok: true };
97	}
98	
99	const urlSchema = z
100	  .string()
101	  .trim()
102	  .max(300)
103	  .refine((v) => v === "" || /^https?:\/\/.+/i.test(v), "Enter a full URL starting with https://");
104	
105	/**
106	 * Save the external review-profile URLs (Trustpilot / HostAdvice / Google) via
107	 * the shared Setting store. These drive the homepage badge links and gate the
108	 * post-purchase review-request email — an empty value means "not set up".
109	 */
110	export async function saveReviewProfileUrls(_prev: ActionState, formData: FormData): Promise<ActionState> {
111	  await requireArea("platform");
112	
113	  const entries: [string, unknown][] = [
114	    ["review_url_trustpilot", formData.get("review_url_trustpilot")],
115	    ["review_url_hostadvice", formData.get("review_url_hostadvice")],
116	    ["review_url_google", formData.get("review_url_google")],
117	  ];
118	
119	  for (const [key, raw] of entries) {
120	    const parsed = urlSchema.safeParse(typeof raw === "string" ? raw : "");
121	    if (!parsed.success) return { error: `${key}: ${parsed.error.issues[0]?.message}` };
122	    await setSetting(key, parsed.data);
123	  }
124	
125	  revalidate();
126	  return { ok: true };
127	}
