import Link from "next/link";
import type { Metadata } from "next";
import { db } from "@/lib/db";
import { PromoBar } from "@/components/marketing/PromoBar";
import { MarketingHeader } from "@/components/marketing/MarketingHeader";
import { MarketingFooter } from "@/components/marketing/MarketingFooter";
import { Reveal } from "@/components/marketing/Reveal";
import { AmbientField } from "@/components/marketing/AmbientField";
import { DeployStage } from "@/components/marketing/DeployStage";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { LogoMarquee } from "@/components/marketing/LogoMarquee";
import { ClaudeBuilder } from "@/components/marketing/ClaudeBuilder";
import { MigrationScreens } from "@/components/marketing/showcase/MigrationScreens";
import { MailInbox } from "@/components/marketing/showcase/MailInbox";
import { DnsManager } from "@/components/marketing/showcase/DnsManager";
import { ServerDashboard } from "@/components/marketing/showcase/ServerDashboard";
import { MatrixTerminal } from "@/components/marketing/MatrixTerminal";
import { NetworkMap } from "@/components/marketing/NetworkMap";
import { PricingExplorer } from "@/components/marketing/PricingExplorer";
import { getPricingExplorerData } from "@/lib/pricing-explorer-data";
import { CurrencyProvider } from "@/components/currency/CurrencyContext";
import { resolveDisplayCurrency } from "@/lib/currency-display";
import { convertAndFormat } from "@/lib/currency";
import { Testimonials } from "@/components/marketing/Testimonials";
import { CustomerReviews } from "@/components/marketing/CustomerReviews";
import { StickyCTA } from "@/components/marketing/StickyCTA";
import { TrustBadges } from "@/components/marketing/TrustBadges";
import { IconNvme, IconShield, IconApps, IconScale } from "@/components/marketing/icons";

export const dynamic = "force-dynamic";

// This IS the public homepage now — the full v9 redesign shipped as `/`
// ("Website Overhaul v2"). Indexable: this is the real site, not the noindex
// /v8·/v9 previews it was drafted as.
export const metadata: Metadata = {
  title: "Nxeon — Your business, online in 47 seconds.",
  description:
    "Nxeon is all-in-one cloud hosting for everyone — websites, apps, game servers and email on enterprise NVMe. We set it up for you, or take full root control. Free migration, automatic SSL, no lock-in.",
  robots: { index: true, follow: true },
};

// HONESTY: the v9 draft's stat bar carried fabricated/aspirational figures
// ("50K active servers", "12 global locations", "47s avg deploy", "10 Gbps
// uplink") that its own source flagged as placeholders "set to real figures
// before any of this ever replaces the public site." This is that moment — it's
// now the public, indexable homepage — so the bar carries only claims that are
// true and already made elsewhere on the site (matching /about and the honest
// live homepage). Same 6-cell layout as v9.
const STATS = [
  ["~60s", "to deploy"],
  ["99.9%", "uptime SLA"],
  ["NVMe", "+ ZFS mirror"],
  ["Full root", "every plan"],
  ["Free", "migration in"],
  ["24/7", "platform monitoring"],
];

const PERF = [
  { icon: <IconNvme />, t: "NVMe SSD storage", d: "Enterprise NVMe on a ZFS mirror — up to 3.5 GB/s sequential read, checksummed, never a throttled shared disk.", bar: 92 },
  { icon: <IconShield />, t: "DDoS protection", d: "Volumetric filtering at the edge, up to 1 Tbps, on by default. Zero configuration.", bar: 100 },
  { icon: <IconScale />, t: "Full root access", d: "It's your box. Any kernel module, any runtime, any port — no managed-host handcuffs.", bar: 78 },
  { icon: <IconApps />, t: "Instant snapshots", d: "One-click backups and restores to a separate pool. Roll back in seconds, not tickets.", bar: 64 },
];

export default async function Home() {
  // The homepage pricing section renders the SAME live <PricingExplorer /> as the
  // /pricing page, built from the shared server helper — one source of truth, so the
  // two pricing charts are identical.
  const [pricingProps, hostingPlans, display] = await Promise.all([
    getPricingExplorerData(),
    db.hostingPlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }).catch(() => []),
    // Visitor's DISPLAY currency + FX rates (geo/cookie → default). DISPLAY ONLY —
    // this page's prices are USD-cents and checkout still charges USD.
    resolveDisplayCurrency(),
  ]);
  // Server-side money formatter for this page's own price strings; the interactive
  // <PricingExplorer/> below converts client-side via the same rates through context.
  const money = (c: number) => convertAndFormat(c, display.currency, display.rate);

  // The cheapest SHARED HOSTING plan, DB-fed — never a hardcoded literal. When no
  // hosting plan exists we simply omit the price chip rather than invent one (a
  // stray "$2.99" fallback here once leaked a hosting price onto a non-hosting
  // card and read like an all-plans price).
  const hostFromCents = hostingPlans.length ? Math.min(...hostingPlans.map((h) => h.priceCents)) : null;

