// schema.org's documented applicationCategory values for SoftwareApplication —
// used verbatim by WebApplicationJsonLd below. Mapped from the tool catalog's
// own ToolCategory so a new tool gets a sane default with zero extra wiring.
const APPLICATION_CATEGORY: Record<ToolCategory, string> = {
  Network: "UtilitiesApplication",
  Developer: "DeveloperApplication",
  Security: "SecurityApplication",
  Servers: "UtilitiesApplication",
};

/**
 * WebApplication structured data for a free tool page. Every field here is
 * verifiably true (it's a real, free, in-browser or API-backed utility — see
 * lib/tools/catalog.ts) — deliberately NOT paired with aggregateRating/review,
 * since no genuine rating data exists for these tools yet. Fabricating one
 * would violate Google's structured-data guidelines; an honest, rating-less
 * WebApplication entity is still valid and still reinforces the page as a real
 * piece of software rather than a thin content page.
 */
function WebApplicationJsonLd({ slug, description }: { slug: string; description: string }) {
  const tool = TOOLS.find((t) => t.slug === slug);
  if (!tool) return null;
  const data = {
    "@context": "https://schema.org",
    "@type": "WebApplication",
    name: tool.name,
    description,
    url: `${APP_URL}/tools/${slug}`,
    applicationCategory: APPLICATION_CATEGORY[tool.category],
    operatingSystem: "Any (web browser)",
    offers: { "@type": "Offer", price: "0", priceCurrency: "USD" },
    isAccessibleForFree: true,
  };
  return <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(data) }} />;
}

